import{_ as s,o as e,c as n,a3 as t}from"./chunks/framework.BwzYn71E.js";const m=JSON.parse('{"title":"塔卫二天师府学院公告","description":"","frontmatter":{"translationSource":{"title":"塔卫二天师府学院公告","archivedAt":"2026-11-23","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=SboV353S6KTHg6EWajOub8","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/talos-ii-tianshi-academy-announcements"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/talos-ii-tianshi-academy-announcements"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/talos-ii-tianshi-academy-announcements"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/talos-ii-tianshi-academy-announcements"}]]},"headers":[],"relativePath":"zh/talos-ii-tianshi-academy-announcements.md","filePath":"zh/page-SboV353S6KTHg6EWajOub8.md"}'),r={name:"zh/talos-ii-tianshi-academy-announcements.md"};function p(o,a,l,i,c,d){return e(),n("div",null,[...a[0]||(a[0]=[t('<div class="logistics-content"><h1 id="塔卫二天师府学院公告" tabindex="-1">塔卫二天师府学院公告 <a class="header-anchor" href="#塔卫二天师府学院公告" aria-label="Permalink to &quot;塔卫二天师府学院公告&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>本页内容更新：</span><a href="/endfield-skydoc/zh/changelog/capture-2026-11-23T06-44-45-722Z-4358a738" title="网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。" aria-label="本页内容更新：2026-11-23. 网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。"><time datetime="2026-11-23T06:44:47.018Z">2026-11-23</time></a><span class="page-updated-zone">（北京时间）</span></p><blockquote><p>源页面 ID：<code>SboV353S6KTHg6EWajOub8</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=SboV353S6KTHg6EWajOub8" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><span id="source-block-rhEbMIPJZuRyzfIw3NG0TC"></span></p><h2 id="群公告文本" tabindex="-1">群公告文本 <a class="header-anchor" href="#群公告文本" aria-label="Permalink to &quot;群公告文本&quot;">​</a></h2><p><span class="mark-grey">*群公告文本应当控制内容为核心告知内容，确保文本量较少。</span></p><p>如果是代肝帮摆的基建让代肝来找售后，我们没有义务免费帮代肝赚钱</p><p>向群聊内寻求蓝图答疑前，请优先选择观看视频/阅读文档/查阅百科，文档链接： <a href="http://43.108.59.96/" target="_blank" rel="noreferrer">http://43.108.59.96/</a> 如果没有问题的答案再寻求群友答疑。</p><p>寻求蓝图答疑请先展示以下物品的报表： （可在报表中点击星标置顶物品方便展示）<span class="mark-yellow">源矿 蓝铁矿 赤铜矿 赤铜块 蓝铁粉末 赤铜粉末 致密源石粉末 赫铜块 息壤 重息壤 壤晶 灼铜块 分离芯 赤铜溶液 气态赤铜 气态赫铜 气态灼铜 中容武陵电池 锦草溶液  </span>  问诊期间禁发无关内容干扰问诊。</p><p>我们不为答疑人员（群管理）以外的群友的回复担保；也请群友先了解，再质疑答疑人员。</p><p>禁止任何违反国家法律和社会公德的不雅昵称（如性别、种族、歧视、侮辱、暴力、色情、地域黑等），违者改名，抗者踢出；</p><p>群聊禁止敏感以及其他易引人不适的内容（包括但不限于封建迷信、淫秽色情、教唆犯罪、不明链接、不明二维码、恐怖、血腥图片、各种广告信息等），违者踢出；</p><p>请文明用语，禁止语言恶毒、无理取闹、造谣生事、人身攻击等消极内容，禁止群内骂战。违者长时间禁言；</p><p><s>不建议聊基建无关内容</s>。有深造意愿、伸冤可私聊管理/群主。</p><p>群满清人，保留管理与最近一周活跃。</p><p>群成员想拉bot入群必须向管理报备征求同意并且对bot负责</p><p><span id="source-block-Jhl7Wbb9J03WQtic78XjeP"></span></p><h2 id="群管理条例" tabindex="-1">群管理条例 <a class="header-anchor" href="#群管理条例" aria-label="Permalink to &quot;群管理条例&quot;">​</a></h2><p><span class="mark-grey">*群管理条例应当清晰记录可能遇到的情况与相应的处罚方式，可以用特殊颜色字作为注释解释条例制定原因。</span></p><p>管理条例的核心目的是维护答疑环境，而非执行神权，围绕这个目标有两个方向，其一为防止炸群，其二为维护答疑氛围。<span class="mark-sky_blue">每个条例应当优先服务于回答问题，而不是严格的惩戒逾矩者。</span></p><p>向群聊内寻求答疑时，不按照要求出示报表，无视答疑人员要求者，无视其提问，此外过于简单的提问亦可无视。<strong>跳脸</strong>者<span class="mark-grey">（at管理提问，但是不按照要求行动）</span>首犯警告，再犯两小时禁言，再犯踢出群聊。</p><p>管理<span class="mark-red">明确为问诊时</span>，期间<strong>禁止聊无关内容干扰答疑</strong>，<span class="mark-red">明确过程即为提醒</span>。初犯禁言十分钟，再犯禁言一小时，再犯禁言一天，屡教不改踢出群聊。对答疑对象，回复无关内容可以滞后处理，答疑期间仅提醒/警告，待答疑完成后再行处罚。</p><p><strong>禁止聊敏感内容</strong>，包括但不限于<span class="mark-red">恐怖、血腥、擦边、金钱交易，封建迷信、淫秽色情、教唆犯罪、不明链接、不明二维码、各种广告信息</span>，无论何时都撤回，首犯十分钟禁言，再犯踢出群聊。<strong>禁止人身攻击</strong>，不做撤回处理，首犯警告，再犯两小时禁言，再犯踢出群聊。对管理首犯在对应群两小时禁言，再犯剥夺管理权限并在所有群一天禁言。</p><p>群人数达<span class="mark-green">475</span>后，早上<span class="mark-grey">（约4:00~12:00）</span>at全体提醒将要清人，在售后群互通有无，晚上（<span class="mark-grey">约18:00~24:00，主要确保提醒与执行有足够间隔）</span><strong>清理成员</strong>，超过一周未发言且无头衔者踢出群聊。</p><p><strong>答疑人员不想答问题</strong>，可以忽略<span class="mark-grey">（如果没有at）</span>或明确说明自己不会/没空<span class="mark-grey">（如果对方at你）（如果时间尴尬可以事后明确</span><span class="mark-grey"><s>比如北京时间凌晨3点</s></span><span class="mark-grey">）</span>，但是一旦选择回答，就需要全程做到尊重对方的困境和疑问，对自己的答疑行为充分负责；<span class="mark-red">当答疑过程遇到无法解决的问题时，应当明确后续跟进人选，并清晰告知提问者后，再转交问题，忌发泄情绪、半途而废。无理由半途而废者首次警告，近期二次再犯剥离管理职权。</span></p><p>在征得至少<span class="mark-sky_blue">两位</span>管理同意后，可以<strong>邀请机器人进入群聊</strong>，但是应当严加管理；若未征得同意邀请机器人，首犯警告并踢出机器人，再犯和机器人一起踢出群聊。若机器人干扰答疑，当场按照普通群友干扰答疑处理，答疑结束后在答疑部门群讨论是否应当对机器人所有者进行处罚<span class="mark-grey">（毕竟是管理们自己同意加进来的嘛）。</span></p><p><strong>再犯</strong><span class="mark-grey">通常指两到三日之内再次触犯，再犯为触犯不同规则时，除了首犯警告外，处罚力度应当逐级增加。例如连续两次人身攻击，触发两小时禁言后，干扰答疑，应当直接禁言一天，而非从十分钟开始重新计数；再例如干扰问诊至禁言一小时，再触犯私邀机器人，应当先警告而非直接踢出（首犯警告），再犯私邀机器人时踢出。</span></p><p><em>PS：群管理有权视具体行为及情节轻重，对群员采取相应的违规处理，包括但不限于改名、禁言、踢除出群（有待商榷的需要和其他管理讨论）</em></p><p><span id="source-block-vA7Yq3jYQxo0dEbUqY38XY"></span></p><h2 id="群管理记录" tabindex="-1">群管理记录 <a class="header-anchor" href="#群管理记录" aria-label="Permalink to &quot;群管理记录&quot;">​</a></h2><p><span class="mark-grey">*群管理记录包含两类。对受罚情况记录应当记录受处罚情况，包括所在群聊，受罚者，大体内容，对应到的管理条例（较容易判定的可以不记录），受罚等级。对群清理记录应当记录提醒时间，执行者，执行时间；群清理不一定要记录。</span></p></div>',1)])])}const g=s(r,[["render",p]]);export{m as __pageData,g as default};
